    }

    def apply_operation(operands, operator):
        b = operands.pop()
        a = operands.pop()
        if operator == '+':
            operands.append(a + b)
        elif operator == '-':
            operands.append(a - b)
        elif operator == '*':
            operands.append(a * b)
        elif operator == '/':
            operands.append(a / b)

    def evaluate(expression):
        operands = []
        operators = []

        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                num = ''
                while i < len(expression) and expression[i].isdigit():
                    num += expression[i]
                    i += 1
                operands.append(int(num))
                i -= 1
            elif expression[i] in precedence:
                while operators and precedence[operators[-1]] >= precedence[expression[i]]:
                    apply_operation(operands, operators.pop())
                operators.append(expression[i])
            i += 1

        while operators:
            apply_operation(operands, operators.pop())

        return operands[0]

    return evaluate(expression)

